steps.command:
set -euo pipefail
python - <<'PY'
import importlib.util,json,shutil,subprocess
bins=['chromium','chromium-browser','google-chrome','google-chrome-stable','firefox','firefox-esr','chromedriver','geckodriver']
installed={x:shutil.which(x) for x in bins}
mods={x:bool(importlib.util.find_spec(x)) for x in ['selenium','playwright']}
versions={}
for name,path in installed.items():
 if path:
  try:
   p=subprocess.run([path,'--version'],text=True,capture_output=True,timeout=10)
   versions[name]=(p.stdout or p.stderr).strip()[:500]
  except Exception as e: versions[name]=type(e).__name__+':'+str(e)
print(json.dumps({'installed':installed,'modules':mods,'versions':versions},sort_keys=True))
print('BROWSER_FAST_ENV_DIAG_COMPLETE')
PY
